package com.kovian.finance.ai.api; import com.kovian.finance.ai.application.*; import com.kovian.finance.ai.domain.*; import com.kovian.finance.transaction.repository.*; import com.kovian.finance.security.CurrentUser; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1/ai/finance") public class FinancialInsightController {final FinancialInsightService service; FinancialInsightController(FinancialTransactionRepository t){service=new FinancialInsightService(t);} @GetMapping("/insights") public List<FinancialInsight> insights(@RequestParam(required=false) UUID ownerId,@RequestParam LocalDate from,@RequestParam LocalDate to){UUID current=CurrentUser.ownerId();if(ownerId!=null&&!current.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation");ownerId=current;if(to.isBefore(from))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid date range");return service.analyze(ownerId,from,to);}}